-- The client's four standard forms (sent 14 Nov 2026), replacing the two drafts (PRD P1-11):
--   business-requirements v2: Tender Creation Form (attached to a tender)
--   supplier-proposal v2:     Bid Submission Form (attached to a bid)
--   business-registration:    Business Registration Form (Forms page)
--   supplier-registration:    Supplier Registration Form (Forms page)
--
-- The client's forms use tick boxes, so the engine gains two field types: choice (one of a list) and
-- checkboxes (any of a list, stored as a JSON array of the chosen labels). A field may also name its
-- section, which only groups fields on screen and in the PDF.
--
-- Signature and company stamp lines become a declaration tick box with name, position and date.
-- Document uploads stay on the tender and bid pages; registration uploads come with verification
-- (PRD P2-02). The draft v1 forms stay for anything saved under them; the site always offers the newest
-- version of each form.

create or replace function private.form_value_problem(field_definition jsonb, field_value jsonb) returns text
language plpgsql
immutable
set search_path = ''
as $$
declare
  field_label text := coalesce(field_definition ->> 'label', field_definition ->> 'name');
  field_type text := field_definition ->> 'type';
  allowed_options jsonb := coalesce(field_definition -> 'options', '[]'::jsonb);
  maximum_length integer;
  chosen jsonb;
begin
  case field_type
    when 'text', 'textarea', 'email', 'date' then
      if jsonb_typeof(field_value) <> 'string' then
        return format('%s must be text.', field_label);
      end if;
      maximum_length := coalesce((field_definition ->> 'maxLength')::integer, case field_type when 'textarea' then 10000 else 500 end);
      if char_length(field_value #>> '{}') > maximum_length then
        return format('%s must be at most %s characters.', field_label, maximum_length);
      end if;
      if field_type = 'email' and (field_value #>> '{}') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
        return format('%s must be an email address.', field_label);
      end if;
      if field_type = 'date' and not private.is_iso_date(field_value #>> '{}') then
        return format('%s must be a date like 2026-11-30.', field_label);
      end if;
    when 'number' then
      if jsonb_typeof(field_value) <> 'number' then
        return format('%s must be a number.', field_label);
      end if;
      if field_definition ? 'minimum' and (field_value #>> '{}')::numeric < (field_definition ->> 'minimum')::numeric then
        return format('%s must be at least %s.', field_label, field_definition ->> 'minimum');
      end if;
    when 'choice' then
      if jsonb_typeof(field_value) <> 'string' or not allowed_options @> jsonb_build_array(field_value) then
        return format('%s must be one of the listed options.', field_label);
      end if;
    when 'checkboxes' then
      if jsonb_typeof(field_value) <> 'array' then
        return format('%s must be a list of the listed options.', field_label);
      end if;
      for chosen in select element from jsonb_array_elements(field_value) as element loop
        if jsonb_typeof(chosen) <> 'string' or not allowed_options @> jsonb_build_array(chosen) then
          return format('%s must only contain the listed options.', field_label);
        end if;
      end loop;
    else
      return format('%s has a type the platform does not support (%s).', field_label, coalesce(field_type, 'none'));
  end case;
  return null;
end;
$$;

